# Alpha driver test result summary (example)
import csv


def load_results(path):
    with open(path, encoding="utf-8") as f:
        return list(csv.DictReader(f))


def count_pass(rows):
    return sum(1 for r in rows if r["判定"] == "合格")


if __name__ == "__main__":
    rows = load_results("alpha_試験結果_0412.csv")
    print("pass:", count_pass(rows), "/", len(rows))
